    'horizontal-pull': { dumbbell: 'One-Arm Dumbbell Row', cable: 'Seated Cable Row', machine: 'Seated Row Machine', barbell: 'Barbell Row', bodyweight: 'Inverted Row' },
    'vertical-pull': { cable: 'Lat Pulldown', machine: 'Assisted Pull-Up Machine', bodyweight: 'Pull-Up' },
    'knee-dominant': { dumbbell: 'Goblet Squat', machine: 'Leg Press', barbell: 'Barbell Back Squat', smith: 'Smith Machine Squat', bodyweight: 'Bodyweight Split Squat' },
    'knee-flexion': { machine: 'Seated Leg Curl Machine', cable: 'Cable Leg Curl', dumbbell: 'Dumbbell Leg Curl', bodyweight: 'Nordic Curl' },
    'hip-dominant': { dumbbell: 'Dumbbell Romanian Deadlift', cable: 'Cable Pull-Through', machine: 'Hip Thrust Machine', barbell: 'Barbell Romanian Deadlift', bodyweight: 'Single-Leg Glute Bridge' },
    calf: { machine: 'Calf Raise Machine', dumbbell: 'Dumbbell Calf Raise', smith: 'Smith Machine Calf Raise', bodyweight: 'Single-Leg Calf Raise' },
    'lateral-delt': { dumbbell: 'Dumbbell Lateral Raise', cable: 'Cable Lateral Raise', machine: 'Lateral Raise Machine' },
