    'elbow-flex': { dumbbell: 'Dumbbell Curl', cable: 'Cable Curl', machine: 'Preacher Curl Machine', barbell: 'Barbell Curl' },
    'elbow-ext': { cable: 'Triceps Pushdown', dumbbell: 'Overhead Dumbbell Extension', machine: 'Triceps Extension Machine', barbell: 'Skull Crusher', bodyweight: 'Bench Dip' },
