/**
 * The gym's level: what the user set, else "big gym" once enough is mapped,
 * else unknown (null — callers treat it as a regular gym).
 */
export function gymLevel(location, mappedCount = 0) {
    if (EQUIPMENT_LEVELS.includes(location?.equipmentLevel)) return location.equipmentLevel;
    return mappedCount >= FULL_GYM_MIN_MACHINES ? 'full' : null;
}

/**
 * Movement names for `pattern` doable at `level`, in implement order
 * (dumbbells → cable → machine → barbell → Smith → bodyweight).
 * @returns {Array<{name:string, implement:string}>}
 */
export function genericFallbacks(pattern, level = 'standard', { exclude = [] } = {}) {
    const byImplement = GENERIC_EXERCISES[pattern] || {};
    const have = LEVEL_IMPLEMENTS[EQUIPMENT_LEVELS.includes(level) ? level : 'standard'];
    const skip = new Set((exclude || []).map(n => String(n).toLowerCase()));
    return have.filter(i => byImplement[i] && !skip.has(byImplement[i].toLowerCase()))
        .map(implement => ({ name: byImplement[implement], implement }));
}

/** "The gym I typically go to": the most-logged gym over the last `days`, newest wins a tie. */
export function usualGym(workouts = [], { today = null, days = 90 } = {}) {
    const floor = today ? new Date(`${today}T12:00:00`).getTime() - days * 86400000 : -Infinity;
    const counts = new Map();
    for (const w of workouts || []) {
        if (!w?.date || !w.completedAt || w.cancelledAt) continue;
        if (new Date(`${w.date}T12:00:00`).getTime() < floor) continue;
        const name = typeof w.location === 'object' ? w.location?.name : w.location;
        if (!name) continue;
        const c = counts.get(name) || { n: 0, last: '' };
        counts.set(name, { n: c.n + 1, last: w.date > c.last ? w.date : c.last });
    }
    let best = null;
    for (const [name, c] of counts) {
        if (!best || c.n > best.n || (c.n === best.n && c.last > best.last)) best = { name, ...c };
    }
    return best ? best.name : null;
}

/** A travel event covering `date` (TP-7 c), or null. */
export function travelOn(date, events = []) {
    return (events || []).find(e => e?.kind === 'travel' && e.date && date >= e.date && date <= (e.endDate || e.date)) || null;
}
